import {INITIAL_PLAN,TASKS,calculate,edgesFor,impacts,connectedIds,recoveries,formatDay,validatePlan} from './model.mjs';
const $=(s)=>document.querySelector(s);
const icons={home:'<path d="m3 10 9-7 9 7M5 9v11h14V9M9 20v-7h6v7"/>',file:'<path d="M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h5"/>',folder:'<path d="M3 7V5h7l3 3h8v12H3z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3"/>',plane:'<path d="m3 10 7 2 5 9 2-1-1-9 5-5c3-3 0-6-3-3l-5 5-9-1z"/>',wifi:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r=".8"/>',bank:'<path d="m3 8 9-5 9 5H3M5 10v8M10 10v8M15 10v8M20 10v8M3 21h18"/>',flag:'<path d="M5 21V3c5-3 8 3 14 0v10c-6 3-9-3-14 0"/>',spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',undo:'<path d="m7 4-4 4 4 4M3 8h10a7 7 0 1 1 0 14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',graph:'<rect x="3" y="9" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M9 12h3V6h3M12 12v6h3"/>'};
function icon(name,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;}
const state={plan:{...INITIAL_PLAN},draft:null,selected:'housing',undo:null,choice:'rebook',acknowledged:false,zoom:1,view:'map',focused:false};
let toastTimer;
const current=()=>state.draft||state.plan;
function announce(message){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${message}</span>`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function statusLabel(task,result){if(result.status==='complete')return 'Complete';if(result.status==='conflict')return 'Appointment at risk';if(result.status==='blocked')return 'Blocked';if(result.status==='late')return 'After arrival';if(result.status==='review')return 'Review connection';if(task.id==='housing')return state.draft?'Simulated date':'Next up';if(task.kind==='fixed')return current().rebooked?'Proposed appointment':'Fixed appointment';if(task.kind==='milestone')return 'Your milestone';return 'Planned';}
function statusMark(s){return s==='complete'?'✓':s==='conflict'||s==='late'?'!':s==='blocked'?'⊘':s==='review'?'◇':'○';}
function renderGraph(){const plan=current(),dates=calculate(plan),baseline=calculate(state.plan),edges=edgesFor(plan),related=connectedIds(state.selected,plan),changed=new Set(state.draft?impacts(state.plan,plan).map(t=>t.id):[]);
 const paths=edges.map(e=>{const a=TASKS.find(t=>t.id===e.from),b=TASKS.find(t=>t.id===e.to);let d;
 if(e.from==='checkin'&&e.to==='ready'){d=`M${a.x+216} ${a.y+56}H824Q836 ${a.y+56} 836 ${a.y+70}V${b.y+40}Q836 ${b.y+56} 820 ${b.y+56}H${b.x+222}`;}else if(a.x===b.x){const x=a.x+108;d=`M${x} ${a.y+112}V${b.y-8}`;}else{const sx=a.x+216,sy=a.y+56,ex=b.x-5,ey=b.y+56;d=`M${sx} ${sy}C${sx+38} ${sy} ${ex-38} ${ey} ${ex} ${ey}`;}
 const affected=changed.has(e.from)&&!e.suggested,selected=e.from===state.selected||e.to===state.selected;return `<path d="${d}" class="${e.suggested?'suggested':''} ${affected?'affected':''} ${selected?'selected-edge':''}" marker-end="url(#${e.suggested?'arrow-dashed':affected?'arrow-active':'arrow-base'})"/>`;}).join('');
 const nodes=TASKS.map(t=>{const r=dates[t.id],delta=r.day!==null&&baseline[t.id].day!==null?r.day-baseline[t.id].day:0;return `<button id="node-${t.id}" data-task="${t.id}" class="task-node ${state.selected===t.id?'selected':''} ${r.status} ${changed.has(t.id)?'changed':''} ${state.focused&&!related.has(t.id)?'unrelated':''}" style="left:${t.x}px;top:${t.y}px" aria-pressed="${state.selected===t.id}" aria-label="${t.title}, ${statusLabel(t,r)}, ${formatDay(r.day)}"><span class="node-meta"><span>${statusMark(r.status)}</span>${statusLabel(t,r)}</span><strong>${t.title}</strong><span class="node-footer"><span class="node-date">${r.day===null?'Awaiting resolution':formatDay(r.day)}</span>${delta?`<span class="change-badge">${delta>0?'+':''}${delta}d</span>`:icon(t.icon)}</span>${state.selected===t.id?'<span class="node-port"></span>':''}</button>`;}).join('');
 $('#graph-canvas').innerHTML=`<svg class="connections" viewBox="0 0 860 562" aria-hidden="true"><defs><marker id="arrow-base" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#b2c8bb" stroke="none"/></marker><marker id="arrow-active" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#b97533" stroke="none"/></marker><marker id="arrow-dashed" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#a28cb8" stroke="none"/></marker></defs>${paths}</svg><div class="graph-stage-label" style="left:24px">01 <span>PREPARE</span></div><div class="graph-stage-label" style="left:300px">02 <span>PUT IT TOGETHER</span></div><div class="graph-stage-label" style="left:576px">03 <span>GET READY</span></div>${nodes}`;
 document.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>selectTask(el.dataset.task));
 $('#steps-list').innerHTML=TASKS.map(t=>`<button class="step-row ${state.selected===t.id?'is-selected':''}" data-list-task="${t.id}">${icon(t.icon)}<span><strong>${t.title}</strong><small>${statusLabel(t,dates[t.id])}</small></span><span class="row-date">${formatDay(dates[t.id].day)}</span>${icon('arrow')}</button>`).join('');
 document.querySelectorAll('[data-list-task]').forEach(el=>el.onclick=()=>selectTask(el.dataset.listTask));fitGraph();}
function selectTask(id){if(!TASKS.some(t=>t.id===id))throw new Error('Unknown task.');state.selected=id;state.focused=true;render();if(innerWidth<=760)$('#inspector').scrollIntoView({behavior:'smooth',block:'start'});}
function fitGraph(){const viewport=$('#graph-viewport'),scale=Math.max(.78,Math.min(1.15,(viewport.clientWidth-28)/860))*state.zoom;$('#graph-canvas').style.zoom=scale;viewport.style.setProperty('--graph-height',`${562*scale+55}px`);$('#zoom-label').textContent=`${Math.round(scale*100)}%`;}
function renderInspector(){const t=TASKS.find(t=>t.id===state.selected),plan=current(),schedule=calculate(plan),r=schedule[t.id],edges=edgesFor(plan),incoming=edges.filter(e=>e.to===t.id),outgoing=edges.filter(e=>e.from===t.id),changes=state.draft?impacts(state.plan,plan):[];
 $('#inspector').innerHTML=`<div class="inspector-eyebrow">${state.draft?'SCENARIO DETAILS':'STEP DETAILS'}<span>${String(TASKS.indexOf(t)+1).padStart(2,'0')} / 08</span></div><div class="detail-icon">${icon(t.icon)}</div><h2>${t.title}</h2><p class="detail-description">${t.description}</p><div class="detail-date"><span>${t.kind==='fixed'?(plan.rebooked?'Proposed slot':'Fixed appointment'):'Planned for'}</span><strong class="${r.status==='conflict'?'text-danger':''}">${formatDay(r.day)}</strong></div>${r.status==='conflict'?`<div class="conflict-note">${icon('info')}<div><strong>This appointment stays put.</strong><p>Your pack would be ready on ${formatDay(schedule.address.day)}. The earliest compatible check-in is ${formatDay(r.earliest)}.</p></div></div>`:''}${r.status==='blocked'?'<div class="conflict-note"><strong>Resolve the check-in conflict to calculate this milestone.</strong></div>':''}${state.draft&&t.id==='housing'?`<div class="date-control"><label for="housing-date">Try a housing confirmation date</label><input id="housing-date" type="date" min="2026-10-01" max="2026-10-20" value="2026-10-${String(plan.housingDay).padStart(2,'0')}"><div class="date-stepper"><button class="date-step" data-day="-1" aria-label="Move housing date one day earlier">−</button><input id="date-slider" type="range" min="1" max="20" value="${plan.housingDay}" aria-label="Housing confirmation day in October"><button class="date-step" data-day="1" aria-label="Move housing date one day later">+</button></div><div class="date-range-label"><span>01 Oct</span><span>20 Oct</span></div></div>`:''}${state.draft&&t.id==='housing'?`<div class="detail-section impact-list"><h3>THE RIPPLE EFFECT <span>${changes.filter(x=>x.id!=='housing').length}</span></h3>${changes.filter(x=>x.id!=='housing').map(x=>`<button class="impact-item" data-impact="${x.id}"><span>${x.after.status==='conflict'?'!':x.after.status==='blocked'?'⊘':'↳'}</span><span><strong>${x.title}</strong><small>${x.after.status==='conflict'?'Fixed appointment · needs a response':x.after.status==='blocked'?'Blocked until the conflict is resolved':`${formatDay(x.before.day)} → ${formatDay(x.after.day)}`}</small></span></button>`).join('')||'<p class="empty-small">No downstream dates change.</p>'}</div>`:`${incoming.length?`<div class="detail-section"><h3>DEPENDS ON</h3>${incoming.map(e=>{const a=TASKS.find(x=>x.id===e.from);return `<button class="dependency-button" data-impact="${a.id}">${icon(a.icon)}<span>${a.title}${e.suggested?'<small>Suggested · does not affect dates</small>':`<small>${e.lag?`${e.lag} calendar day${e.lag>1?'s':''} after`:'Ready to use'}</small>`}</span>${icon('arrow')}</button>`;}).join('')}</div>`:''}${outgoing.length?`<div class="detail-section"><h3>THIS UNLOCKS</h3>${outgoing.map(e=>`<button class="unlock-item" data-impact="${e.to}"><span>↳</span>${TASKS.find(x=>x.id===e.to).title}${e.suggested?'<span class="suggestion-tag">?</span>':''}</button>`).join('')}</div>`:!incoming.length?'<div class="detail-section"><h3>INDEPENDENT STEP</h3><p class="empty-small">Changes elsewhere won’t move this task.</p></div>':''}`}
 ${t.id==='bank'&&!plan.bankReviewed?`<div class="assumption-card"><span>${icon('spark')} A connection to question</span><p>Do you need the address pack to compare banks? This suggested link isn’t used in your schedule yet.</p><div><button id="accept-link" class="button button-outline">Keep this link</button><button id="dismiss-link" class="button button-quiet">Dismiss</button></div></div>`:`<div class="evidence-card"><span>${icon('file')} ${t.source}</span><p>“${t.note}”</p><small>${t.sourceType}${t.id==='bank'&&plan.bankReviewed?plan.bankDependency?' · Link accepted':' · Link dismissed':''}</small>${t.id==='bank'&&plan.bankReviewed?'<button class="button button-quiet" id="reopen-link">Reopen as a suggestion</button>':''}</div>`}
 <div class="inspector-bottom">${state.draft?`<button class="button button-primary full-width" id="inspector-compare">${schedule.checkin.status==='conflict'?'Compare ways forward':'Review this change'} ${icon('arrow')}</button><p>Exploring a scenario. Your saved plan is unchanged.</p>`:t.kind==='complete'?'<p>This step is complete in the sample plan.</p>':`<button class="button button-outline" id="detail-simulate">${t.id==='housing'?'Try a different date':'Explore a housing delay'} ${icon('arrow')}</button><p>Preview the ripple before changing your plan.</p>`}</div>`;
 document.querySelectorAll('[data-impact]').forEach(el=>el.onclick=()=>selectTask(el.dataset.impact));
 $('#detail-simulate')?.addEventListener('click',()=>startSimulation());$('#inspector-compare')?.addEventListener('click',openComparison);$('#reopen-link')?.addEventListener('click',reopenLink);$('#accept-link')?.addEventListener('click',()=>reviewLink(true));$('#dismiss-link')?.addEventListener('click',()=>reviewLink(false));
 $('#housing-date')?.addEventListener('change',e=>{const input=e.target,match=/^2026-10-(\d{2})$/.exec(input.value);if(!match||+match[1]<1||+match[1]>20){input.value=`2026-10-${String(current().housingDay).padStart(2,'0')}`;announce('Choose a date between 1 and 20 October.');return;}setHousingDay(+match[1]);});
 $('#date-slider')?.addEventListener('change',e=>setHousingDay(+e.target.value,'date-slider'));
 document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>setHousingDay(Math.max(1,Math.min(20,current().housingDay+Number(el.dataset.day)))));}
function renderTimeline(){const schedule=calculate(current()),base=calculate(state.plan),position=d=>Math.max(0,Math.min(100,(d-1)/30*100));const rows=TASKS.filter(t=>t.kind!=='complete').map(t=>{const r=schedule[t.id],b=base[t.id],diff=!!state.draft&&r.day!==b.day;return `<div class="timeline-row"><button class="timeline-label ${state.selected===t.id?'active':''}" data-timeline="${t.id}">${icon(t.icon)}${t.title}</button><div class="time-grid">${diff&&b.day!==null?`<span class="ghost-date" style="left:${position(b.day)}%" aria-hidden="true"></span>`:''}${r.day!==null?`<button class="time-point ${r.status} ${diff?'shifted':''} ${t.id==='housing'&&state.draft?'draggable-date':''}" data-point="${t.id}" style="left:${position(r.day)}%" aria-label="${t.title}, ${formatDay(r.day)}${t.id==='housing'&&state.draft?', drag to change or use the date field':''}" title="${formatDay(r.day)}"><span>${String(r.day).padStart(2,'0')}</span></button>`:'<span class="blocked-timeline">Waiting for a new check-in plan</span>'}<span class="arrival-line" style="left:${position(18)}%" aria-hidden="true"></span></div></div>`;}).join('');
 $('.timeline-section').innerHTML=`<div class="timeline-heading"><strong>Your October timeline</strong><span>${state.draft?'<i class="ghost-key"></i> Original plan &nbsp; <i class="new-key"></i> Scenario':'Follow a date back to its dependencies'}</span></div><div class="timeline-ruler"><span>OCTOBER 2026</span><div>${[1,6,12,18,24,31].map(d=>`<span style="left:${position(d)}%">${String(d).padStart(2,'0')}</span>`).join('')}</div></div>${rows}<div class="timeline-footnote"><span>${state.draft?'Drag the housing date, or use the date field.':'Select any date to inspect the step.'}</span><span>Arrival: 18 Oct</span></div>`;
 document.querySelectorAll('[data-timeline]').forEach(el=>el.onclick=()=>selectTask(el.dataset.timeline));document.querySelectorAll('[data-point]').forEach(el=>{el.onclick=()=>selectTask(el.dataset.point);if(el.dataset.point==='housing'&&state.draft)bindDateDrag(el);});}
function bindDateDrag(el){el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();const rect=el.parentElement.getBoundingClientRect();let day=current().housingDay;el.setPointerCapture(e.pointerId);el.classList.add('dragging');const move=event=>{day=Math.max(1,Math.min(20,Math.round((event.clientX-rect.left)/rect.width*30)+1));el.style.left=`${(day-1)/30*100}%`;el.querySelector('span').textContent=String(day).padStart(2,'0');};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',cancel);state.selected='housing';setHousingDay(day);};const cancel=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);render();};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end,{once:true});el.addEventListener('pointercancel',cancel,{once:true});});}
function render(){const focused=document.activeElement;const focusId=focused?.id;const focusAttributes=['data-task','data-list-task','data-impact','data-timeline','data-point','data-day'];const focusKey=focusAttributes.find(k=>focused?.hasAttribute(k));const focusValue=focusKey?focused.getAttribute(focusKey):null;const plan=current(),schedule=calculate(plan),conflict=schedule.checkin.status==='conflict',late=schedule.ready.status==='late';$('#plan-health').textContent=conflict?'One appointment needs a new plan':late?'Your preparation extends past arrival':state.draft?'This scenario keeps your plan on track':state.plan.rebooked?'A new plan, with a little breathing room':'Your plan has room to breathe';$('#plan-summary').textContent=conflict?`Address pack ready ${formatDay(schedule.address.day)} · check-in fixed on ${formatDay(plan.appointmentDay)}`:late?`Preparation ends ${formatDay(schedule.ready.day)} · arrival is 18 Oct`:`8 connected steps · 2 complete${plan.bankReviewed?'':' · 1 assumption to review'}`;$('.plan-overview').classList.toggle('warning',conflict||late);$('.overview-check').textContent=conflict||late?'!':'✓';$('#simulate-button').innerHTML=state.draft?`${icon('close')} Exit simulation`:`${icon('spark')} Simulate a change`;$('#simulate-button').classList.toggle('is-simulating',!!state.draft);$('#undo-button').hidden=!state.undo;$('#simulation-banner').hidden=!state.draft;if(state.draft){$('#simulation-caption').textContent=`Housing: ${formatDay(state.plan.housingDay)} → ${formatDay(plan.housingDay)}`;$('#banner-compare').textContent=conflict?'Compare ways forward':'Review change';}renderGraph();renderInspector();renderTimeline();$('#steps-list').hidden=state.view!=='list';$('#graph-viewport').hidden=state.view!=='map';document.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===state.view);el.setAttribute('aria-pressed',String(el.dataset.view===state.view));});if(state.view==='map')fitGraph();const restore=focusId?document.getElementById(focusId):focusKey?document.querySelector(`[${focusKey}="${focusValue}"]`):null;if(restore&&!restore.hidden)restore.focus({preventScroll:true});else if(focusId==='accept-link'||focusId==='dismiss-link')$('#node-bank')?.focus({preventScroll:true});}
function startSimulation(day){state.draft={...state.plan,housingDay:day??Math.min(20,state.plan.housingDay+7)};validatePlan(state.draft);state.selected='housing';state.focused=false;render();announce('Simulation started. Your plan has not changed.');if(innerWidth<=760)$('#inspector').scrollIntoView({behavior:'smooth'});}
function setHousingDay(day,restore){if(!Number.isInteger(day)||day<1||day>20)throw new Error('Housing date must be an integer from 1 to 20 October.');if(!state.draft)startSimulation(day);else{state.draft.housingDay=day;render();}if(restore)$('#'+restore)?.focus({preventScroll:true});}
function cancelSimulation(){state.draft=null;render();announce('Scenario discarded. Your plan is unchanged.');}
function reviewLink(accepted){if(state.draft){state.draft.bankDependency=accepted;state.draft.bankReviewed=true;}else{state.undo={...state.plan};state.plan={...state.plan,bankDependency:accepted,bankReviewed:true};}render();announce(accepted?'Connection accepted. Banking now follows the address pack.':'Connection dismissed. Banking stays independent.');}
function reopenLink(){if(state.draft){state.draft.bankDependency=false;state.draft.bankReviewed=false;}else{state.undo={...state.plan};state.plan={...state.plan,bankDependency:false,bankReviewed:false};}render();$('#accept-link')?.focus({preventScroll:true});announce('Connection reopened as a suggestion. It no longer changes dates.');}
function undo(){if(!state.undo)return;state.plan={...state.undo};state.undo=null;state.draft=null;state.selected='housing';state.focused=false;render();$('#simulate-button').focus({preventScroll:true});announce('Previous plan restored.');}
function showDialog(html,wide=false){const root=$('#overlay-root');root.innerHTML=`<dialog class="dialog ${wide?'dialog-wide':''}" aria-labelledby="dialog-title"><button class="dialog-close icon-button" aria-label="Close dialog">${icon('close')}</button>${html}</dialog>`;const dialog=root.querySelector('dialog');dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});return dialog;}
function openComparison(){if(!state.draft)return;state.acknowledged=false;const conflicted=calculate(state.draft).checkin.status==='conflict',options=conflicted?recoveries(state.draft):[{id:'keep',title:'Use the simulated date',label:'An updated plan',description:'Keep your new housing date and the dependent dates shown in the preview.',assumption:'These are planning dates. This does not change any external booking.',plan:{...state.draft}}];state.choice=options[0].id;
const dialog=showDialog(`<div class="dialog-kicker">${icon('graph')} A WAY FORWARD</div><h2 id="dialog-title">${conflicted?'A delay doesn’t have to derail your move.':'A small change. The full picture.'}</h2><p class="dialog-intro">${conflicted?'Compare the trade-offs. Choose which assumption you want to plan around.':'Review the dates before applying this change to your plan.'}</p><div class="recovery-options">${options.map((o,i)=>{const dates=calculate(o.plan);return `<label class="recovery-option ${i===0?'chosen':''}"><input type="radio" name="recovery" value="${o.id}" ${i===0?'checked':''}><span class="option-topline"><span>${o.label}</span><span class="radio-mark"></span></span><strong>${o.title}</strong><p>${o.description}</p><dl><div><dt>Housing confirmed</dt><dd>${formatDay(o.plan.housingDay)}</dd></div><div><dt>Office check-in</dt><dd>${formatDay(o.plan.appointmentDay)}</dd></div><div><dt>Ready for arrival</dt><dd class="${dates.ready.day>18?'text-danger':'text-green'}">${formatDay(dates.ready.day)}</dd></div></dl><div class="option-assumption">${icon('info')}<span>${o.assumption}</span></div></label>`;}).join('')}</div><div id="change-review"></div><label class="acknowledgement"><input type="checkbox" id="acknowledge"><span>I understand these dates depend on the assumptions above. Applying this updates the demo plan only.</span></label><div class="dialog-footer"><span id="apply-summary"></span><button class="button button-primary" id="apply-plan" disabled>Apply to my plan ${icon('arrow')}</button></div>`,true);
const update=()=>{const option=options.find(o=>o.id===state.choice),changes=impacts(state.plan,option.plan);$('#change-review').innerHTML=`<div class="change-review-title"><strong>${changes.length} steps will change</strong><span>BEFORE <span>→</span> AFTER</span></div>${changes.map(t=>`<div class="review-row"><span>${t.title}</span><span><del>${t.id==='bank'&&t.before.day===t.after.day?'Suggested link':formatDay(t.before.day)}</del>${icon('arrow')}<strong>${t.id==='bank'&&t.before.day===t.after.day?(option.plan.bankDependency?'Accepted':'Dismissed'):formatDay(t.after.day)}</strong></span></div>`).join('')||'<p class="empty-small">No dates will change.</p>'}`;$('#apply-summary').textContent=calculate(option.plan).ready.day>18?'Preparation will extend past your arrival.':'You can undo this change.';dialog.querySelectorAll('.recovery-option').forEach(el=>el.classList.toggle('chosen',el.querySelector('input').value===state.choice));$('#apply-plan').disabled=!state.acknowledged;};
dialog.querySelectorAll('[name="recovery"]').forEach(el=>el.onchange=()=>{state.choice=el.value;state.acknowledged=false;$('#acknowledge').checked=false;update();});$('#acknowledge').onchange=e=>{state.acknowledged=e.target.checked;$('#apply-plan').disabled=!state.acknowledged;};$('#apply-plan').onclick=()=>{if(!state.acknowledged)return;const option=options.find(o=>o.id===state.choice);state.undo={...state.plan};state.plan={...option.plan};state.draft=null;state.selected='housing';state.focused=false;dialog.close();render();$('#undo-button').focus({preventScroll:true});announce('Plan updated. Use Undo to return to your previous dates.');};update();}
function showAbout(){showDialog(`<div class="dialog-kicker">${icon('graph')} MOVEGRAPH</div><h2 id="dialog-title">Seven cities.<br>A few things learned along the way.</h2><p class="dialog-intro">MoveGraph is inspired by Hayk’s experience living in seven cities over four years: the hard part of moving is often understanding how one requirement connects to another.</p><div class="about-facts"><p><strong>A small, illustrative scenario.</strong> The dates, coordinator note, and dependencies in this Berlin move are fictional planning assumptions. They are not official immigration or registration requirements.</p><p><strong>A suggestion is yours to question.</strong> Dashed connections do not affect the schedule until you accept them. Appointments stay fixed until you explicitly choose a revised plan.</p><p><strong>A prototype built with AI assistance.</strong> Date changes are calculated with local rules. No live AI service is connected and no external bookings are changed. Refreshing restores the sample plan.</p></div><button class="button button-primary" id="about-done">Back to my move ${icon('arrow')}</button>`);$('#about-done').onclick=()=>document.querySelector('dialog').close();}
$('.surface-toolbar').innerHTML=`<div class="view-title">${icon('graph')} The bigger picture</div><div class="view-switch" aria-label="Plan presentation"><button data-view="map" class="active" aria-pressed="true">Map</button><button data-view="list" aria-pressed="false">Steps</button></div><div class="zoom-controls"><button class="icon-button" id="zoom-out" aria-label="Zoom out">−</button><span id="zoom-label">100%</span><button class="icon-button" id="zoom-in" aria-label="Zoom in">+</button><button class="icon-button" id="reset-view" aria-label="Fit graph and clear focus">⤢</button></div>`;
$('#graph-viewport').insertAdjacentHTML('afterend','<div id="steps-list" class="steps-list" hidden></div>');$('.graph-legend').innerHTML='<span><i class="legend-line"></i> Accepted dependency</span><span><i class="legend-line dotted"></i> Suggested</span><span><i class="legend-dot"></i> Complete</span>';
$('.workspace').insertAdjacentHTML('beforebegin',`<div id="simulation-banner" class="simulation-banner" hidden><div>${icon('spark')}<strong>Simulation</strong><span id="simulation-caption"></span></div><div><button class="button button-quiet" id="discard-simulation">Discard</button><button class="button button-primary" id="banner-compare">Compare ways forward</button></div></div>`);
$('#simulate-button').insertAdjacentHTML('beforebegin',`<button class="button button-quiet" id="undo-button" hidden>${icon('undo')} Undo change</button>`);const actions=document.createElement('div');actions.className='heading-actions';actions.append($('#undo-button'),$('#simulate-button'));$('.page-heading').append(actions);
$('#simulate-button').onclick=()=>state.draft?cancelSimulation():startSimulation();$('#about-button').onclick=showAbout;$('#footer-about').onclick=showAbout;$('#undo-button').onclick=undo;$('#discard-simulation').onclick=cancelSimulation;$('#banner-compare').onclick=openComparison;$('#zoom-in').onclick=()=>{state.zoom=Math.min(1.75,state.zoom+.15);fitGraph();};$('#zoom-out').onclick=()=>{state.zoom=Math.max(.8,state.zoom-.15);fitGraph();};$('#reset-view').onclick=()=>{state.zoom=1;state.focused=false;render();$('#graph-viewport').scrollTo({left:0,top:0,behavior:'smooth'});};document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{state.view=el.dataset.view;render();});window.addEventListener('resize',fitGraph);render();
const context=document.modelContext;
if(context?.registerTool){const controller=new AbortController(),snapshot=()=>({plan:{...state.plan},simulation:state.draft?{...state.draft}:null,selectedTask:state.selected,schedule:calculate(current())}),definitions=[
 {name:'read_move_plan',title:'Read move plan',description:'Read the saved plan, staged simulation, and calculated dates. Does not change the plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>snapshot()},
 {name:'stage_housing_change',title:'Simulate housing confirmation date',description:'Start or update a housing date simulation for October 2026. Does not apply it to the saved plan.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1,maximum:20}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='day')||!Number.isInteger(input.day)||input.day<1||input.day>20)throw new Error('Provide an integer day from 1 to 20.');setHousingDay(input.day);return snapshot();}},
 {name:'inspect_move_step',title:'Inspect a move step',description:'Select a step and show its dependencies and evidence in the detail panel.',inputSchema:{type:'object',properties:{taskId:{type:'string',enum:TASKS.map(t=>t.id)}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='taskId'))throw new Error('Provide a taskId.');selectTask(input.taskId);return snapshot();}},
 {name:'discard_move_simulation',title:'Discard simulation',description:'Discard the staged simulation and restore the saved plan in the interface.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{cancelSimulation();return snapshot();}}
 ];for(const tool of definitions){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
